// Constants

#define PI 3.14159

const vec3 starPos = vec3(1, 0, .5);
const vec3 yellow = vec3(255., 250., 130.) / 255.;
const vec3 blue = vec3(204., 232., 246.) / 255.;

// SDF Functions and operations

// Signed Distance Field (SDF in short) is a function that returns closest distance to an geometric figure
// from the given point. It is signed, because it returns negative distance if the point it inside the figure.
// There is bunch of geometric figures you can find a function that meet those conditions. Sphere is probably the easiest though.
// You can create more complex shapes combining SDF values using different operations, for example union of two shapes is just 
// min(sdf1, sdf2). There are also smoothing operations which gives clay like effect.
// With the same opeartions you can describe complex scenes and render them using Raymarching algorithm described later.
// More on SDF functions and operations: https://iquilezles.org/articles/distfunctions/

float sdSphere(vec3 p, float r) {
    return length(p) - r;
}

float ellipsoid( vec3 p, vec3 r )
{
  float k0 = length(p/r);
  float k1 = length(p/(r*r));
  return k0*(k0-1.0)/k1;
}

float sdCappedTorus( vec3 p, vec2 sc, float ra, float rb)
{
  p.x = abs(p.x);
  float k = (sc.y*p.x>sc.x*p.y) ? dot(p.xy,sc) : length(p.xy);
  return sqrt( dot(p,p) + ra*ra - 2.0*ra*k ) - rb;
}

// iq's implementation of 3d Bezier SDF:
// https://www.shadertoy.com/view/ldj3Wh
vec2 sdBezier( vec3 p, vec3 b0, vec3 b1, vec3 b2 )
{
    b0 -= p;
    b1 -= p;
    b2 -= p;

    vec3 b01 = cross(b0,b1);
    vec3 b12 = cross(b1,b2);
    vec3 b20 = cross(b2,b0);

    vec3 n =  b01+b12+b20;

    float a = -dot(b20,n);
    float b = -dot(b01,n);
    float d = -dot(b12,n);

    float m = -dot(n,n);

    //vec3  g = b*(b2-b1) + d*(b1-b0) + a*(b2-b0)*0.5;
    vec3  g =  (d-b)*b1 + (b+a*0.5)*b2 + (-d-a*0.5)*b0;
    float f = a*a*0.25-b*d;
    vec3  k = b0-2.0*b1+b2;
    float t = clamp((a*0.5+b-0.5*f*dot(g,k)/dot(g,g))/m, 0.0, 1.0 );

    return vec2(length(mix(mix(b0,b1,t), mix(b1,b2,t),t)),t);
}

vec4 opElongate( in vec3 p, in vec3 h )
{   
    vec3 q = abs(p)-h;
    return vec4( max(q,0.0), min(max(q.x,max(q.y,q.z)),0.0) );
}


float opSmoothSubtraction( float d1, float d2, float k )
{
    float h = clamp( 0.5 - 0.5*(d2+d1)/k, 0.0, 1.0 );
    return mix( d2, -d1, h ) + k*h*(1.0-h);
}

float opSmoothUnion( float d1, float d2, float k )
{
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h);
}


// Returns a rotation matrix describing rotation around axis 'a' by an angle 't' in radians
mat3 makeRot(float t, vec3 a) {
    float c = cos(t);
    float s = sin(t);
    float d = 1.0 - c;

    float x = a.x * d;
    float y = a.y * d;
    float z = a.z * d;

    float axay = x * a.y;
    float axaz = x * a.z;
    float ayaz = y * a.z;

    return mat3(
             vec3(   c + x * a.x, axay - s * a.z, axaz + s * a.y),
             vec3(axay + s * a.z,    c + y * a.y, ayaz - s * a.x),
             vec3(axaz - s * a.y, ayaz + s * a.x,    c + z * a.z)
           );
}

// To create star shape I take several rotated elipsoids and 
// blend them together using smooth union operation
float StarsSDF(vec3 point) {
    vec3 mirrorPoint = vec3(abs(point.x), point.y, point.z);
    vec3 starPoint = mirrorPoint - starPos; 

    float star = 10000.0;
    for(int i = 0; i < 5; i++) {
        float r = (float(i) * 2.0 * PI) / 5.0 + PI;
        mat3 rot = makeRot(r, vec3(0, 0, 1)) * makeRot(0.4, vec3(0, 1, 0)) * makeRot(-0.6, vec3(1, 0, 0));
        float s = ellipsoid(rot * starPoint + vec3(0., 0.2, 0.), vec3(0.15, 0.3, 0.15));
        star = opSmoothUnion(star, s, 0.2);
    }

    return star;
}

// The function that returns Distance Field value for given point. 
// In other words it describes all the shapes in the scene
// returns x - SDF, y - object id
vec2 SDF(vec3 point) {
    float sdf = 100000.0;
    vec2 ret = vec2(sdf, 0.0);

    // headband
    vec3 headbandPoint = point - vec3(0, -4.4, -0.5);
    headbandPoint = makeRot(0.2, vec3(1, 0, 0)) * headbandPoint;
    headbandPoint = opElongate(headbandPoint, vec3(0, 0, 0.3)).xyz;
    //headbandPoint = makeRot(0.1, vec3(1, 0, 0)) * headbandPoint;
    float headband = sdCappedTorus(headbandPoint, vec2(1, 0), 3.0, .1);


    // Stars
    float star = StarsSDF(point);

    // stems     
    vec3 mirrorPoint = vec3(abs(point.x), point.y, point.z);
    vec3 starPoint = mirrorPoint - starPos;

    float stemOffsetX = 0.6;
    vec2 b = sdBezier(mirrorPoint, vec3(stemOffsetX, -1.5, 0), vec3(stemOffsetX, -.5, 0), starPos);
    float stem = b.x - 0.03;

    // head
    float head = sdSphere(point - vec3(0, -4.4, -.8), 3.1);
    head = opSmoothSubtraction(headband, head, .2);

    //////
    ret = ret.x < headband ? ret : vec2(headband, 1.0);
    ret = ret.x < stem ? ret : vec2(stem, 1.0);
    ret = ret.x < star ? ret : vec2(star, 2.0);
    ret = ret.x < head ? ret : vec2(head, 3.0);

    return ret;
}

// To render SDF scene we use algorithm called ray marching.
// It's conceptually similar to ray tracing but instead of solving intersection
// we "march" on given ray, meaning we compute a point on the ray at given distance until SDF is very close to 0, 
// which means we hit something, or iterations count (or distance) hits the threshold, in which case we didn't hit anything.
// Each step we increase distance by SDF value - we can safely done that, because by the definition, the closes object 
// is at least at distance away.
// This function returns distance on ray, at which we hit something (or end value if we didn't) but also distance to the 
// star objects (which is used for the waves effect) and object id (for coloring). Everything packed in one vec3.
// More about raymarching: https://iquilezles.org/articles/raymarchingdf/
vec3 raymarch(vec3 rayOrigin, vec3 rayDirection, float start, float end) {
    float depth = start;
    float id = 1.0;
    float minDist  = 10000.0;
    float starDist = 10000.0;

    for(int i = 0; i < 126; i++) {
        vec3 point = rayOrigin + depth * rayDirection;

        vec2 sdfRet = SDF(point);
        float dist = sdfRet.x;

        if(dist < minDist) {
            minDist = dist;
            id = sdfRet.y;
        }

        float newStarDist = StarsSDF(point);
        starDist = min(starDist, newStarDist);

        if(dist < 0.001) return vec3(depth, starDist, id);

        depth += dist;
        if(depth >= end) return vec3(end, starDist, id);
    }

    return vec3(end, starDist, id);
}

// It's hard to analytically find the normal of a generic SDF function
// so we typically take the bruteforce approach by sampling SDF at four
// points and calculating normal from that
// more on that topic: https://iquilezles.org/articles/normalsSDF/
vec3 calcNormal( in vec3 p ) // for function f(p)
{
    const float h = 0.0001; // replace by an appropriate value
    const vec2 k = vec2(1,-1);
    return normalize( k.xyy*SDF( p + k.xyy*h ).x + 
                      k.yyx*SDF( p + k.yyx*h ).x + 
                      k.yxy*SDF( p + k.yxy*h ).x + 
                      k.xxx*SDF( p + k.xxx*h ).x );
}

mat4 viewMatrix(vec3 pos, vec3 target, vec3 up) {
	vec3 f = normalize(target - pos);
	vec3 s = normalize(cross(f, up));
	vec3 u = cross(s, f);
	return mat4(
		vec4(s, 0.0),
		vec4(u, 0.0),
		vec4(-f, 0.0),
		vec4(0.0, 0.0, 0.0, 1)
	);
}


vec3 rayDirection(float fieldOfView, vec2 size, vec2 fragCoord) {
    vec2 xy = fragCoord - size / 2.0;
    float z = size.y / tan(radians(fieldOfView) / 2.0);
    return normalize(vec3(xy, -z));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Camera animation.
    float angle = sin(iTime / 2.0) * 0.4 + PI / 2.0;
    vec3 cameraPos = vec3(cos(angle), 0.0, sin(angle)) * 10.0;
    cameraPos.y = 2.5 + cos(iTime + 0.4) * 0.3;

    // Calculate ray direction from current screen pixel
    mat4 camera = viewMatrix(
                    cameraPos,
                    vec3(0.0, 0.0, 0.0),
                    vec3(0.0, 1.0, 0.0)
                  );

    vec3 dir = rayDirection(45.0, iResolution.xy, fragCoord);
    dir = (camera * vec4(dir, 1.0)).xyz;

    // sample scene SDF
    vec3 rRes = raymarch(cameraPos, dir, 0.0, 100.0);
    float dist     = rRes.x;
    float starDist = rRes.y;
    float id       = rRes.z;

    vec3 col = vec3(0);

    // This creates the waves effect.
    // It takes distance to the stars to sample frequency of the audio.
    float t = 1.0 - fract(starDist / 2.0 - iTime / 3.0);

    // Here I reduce the number of samples 16 time by snapping
    // the texture sample point. I multiply it by 512.0 because
    // the audio data "texture" is 512 pixels wide.
    const float snapPoint = 16.0;
    float tFloor = floor(t * 512.0 / snapPoint) * snapPoint; 
    float tFraq = ((t * 512.0) - tFloor) / snapPoint;

    // back to <0; 1> range
    t = tFloor / 512.0;

    // I sample texture 2 times so I can blend them together giving smoother
    // transition. 
    float freq1 = texture(iChannel0, vec2(t, 0)).x;
    float freq2 = texture(iChannel0, vec2(t - (snapPoint / 512.0), 0)).x;
    float freq = mix(freq1, freq2, 1.0 - tFraq);

    // If I use just one frequency the effect is also cool, you can uncomment this
    // line and recompile by cliking the play button just under the code window
    // freq = freq1;

    // Here I do some processing of the given value in order to the colors of the wave brighter
    freq = freq * freq;
    freq *= 3.0 * (t + 1.0);

    col += vec3(34, 47, 102) / 255. * freq;

    // If the ray hit something, we calculate color of the object
    // with very simple shading. Dot function in this case returns 
    // cosine of an angle between object normal and light direction.
    // Then, I move it to the <0, 1> range and multiply by object color
    // to get nice toon shading
    if(dist < 100.0) {
        vec3 hitPoint = cameraPos + dir * dist;
        vec3 normal = calcNormal(hitPoint);
        float ndotl = dot(normal, vec3(0.2, 1, 0.2)) * 0.5 + 0.5;

        col += (id == 1.0 || id == 2.0 ? yellow : blue) * ndotl;
    }
    else {
        // If we didn't hit anything  I just put the waveform of the audio 
        // in the background to make it more interesting 
        // I'm not sure if I didn't overdo it
        float wave = texture(iChannel0, vec2(uv.x, 1)).x;
        wave = (1.0 -  smoothstep(0.0, 0.05, abs(wave - uv.y - 0.5))) * 0.2;
        col += wave * yellow;
    }

    // Output to screen
    fragColor = vec4(col,1.0);
}
